// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface SurgicalStatisticsOut {
  date_from: string;
  date_to: string;
  /** Operations that ended in the period */
  operations: number;
  with_anaesthetist: number;
  chart_gap_minutes: number;
  measures: SurgicalMeasureOut[];
  adverse_events: AdverseEventSummaryOut;
  by_surgeon: SurgeonStatOut[];
  by_theatre: TheatreStatOut[];
}

export interface SurgicalMeasureOut {
  measure: "pre_op_note" | "pre_anaesthesia" | "pre_induction" | "monitoring" | "sign_in" | "checklist" | "time_out" | "anaesthesia_record" | "operative_note" | "recovery_observed" | "recovery_criteria";
  label: string;
  /** The MSDS indicator it evidences */
  reference: string;
  applicable: number;
  met: number;
  pct: number | null;
}

/** The theatre adverse events: incidents of the Anaesthesia and Surgery areas reported against an operation. */
export interface AdverseEventSummaryOut {
  /** Events that occurred in the period (withdrawn reports left out) */
  total: number;
  /** Events not closed yet, of any date */
  open_now: number;
  /** By area: Anaesthesia, Surgery */
  by_kind: CountOut[];
  /** By harm */
  by_severity: CountOut[];
  /** By incident type */
  by_category: CountOut[];
}

export interface CountOut {
  key: string;
  count: number;
}

export interface SurgeonStatOut {
  employee_id: number;
  name: string;
  operations: number;
  operative_notes_signed: number;
  checklists_complete: number;
  adverse_events: number;
}

export interface TheatreStatOut {
  ot_id: number | null;
  name: string | null;
  operations: number;
  adverse_events: number;
}

