/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** Surgical care statistics — GET /api/v1/ot/clinical-statistics (who may call: holders of ot.clinical_statistics.view). */
export function clinicalStatistics(query?: { date_from?: string | null; date_to?: string | null }): Promise<SurgicalStatisticsOut> {
  return api<SurgicalStatisticsOut>("GET", withQuery(`/ot/clinical-statistics`, query), undefined);
}

/** The incident register — GET /api/v1/incidents (who may call: holders of incident.view or incident.report or ot.clinical_statistics.view). */
export function listIncidents(query?: { status?: "Reported" | "UnderReview" | "Analysed" | "Closed" | "Withdrawn" | null; type_code?: string | null; area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; sentinel_only?: boolean; harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death" | null; department_id?: number | null; booking_id?: number | null; patient_id?: number | null; date_from?: string | null; date_to?: string | null; mine?: boolean; open_only?: boolean; limit?: number }): Promise<IncidentOut[]> {
  return api<IncidentOut[]>("GET", withQuery(`/incidents`, query), undefined);
}
